#!/usr/bin/env bash
# Self-contained CSS для run-finale (bash-only, без PowerShell).
set -euo pipefail

ROUND="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
OUT="$ROUND/lab-base.css"

# Раунд самодостаточен: токены и компоненты целиком в styles.css
sources=(
  "$ROUND/styles.css"
)

{
  cat <<'HDR'
/* Auto-generated by sync-lab.sh - do not edit by hand */
/* Round: run-finale */
/* Sources: styles.css */

HDR
  for src in "${sources[@]}"; do
    if [[ ! -f "$src" ]]; then
      echo "sync-lab.sh: missing source: $src" >&2
      exit 1
    fi
    cat "$src"
    printf '\n'
  done
} > "$OUT"

echo "OK: $OUT"
